def solve(grid):
    """Solve ARC task by finding target shape and filling appropriately"""
    h, w = len(grid), len(grid[0])

    # Count color frequencies
    counts = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            counts[color] = counts.get(color, 0) + 1

    # Background is most common
    bg_color = max(counts, key=counts.get)

    # Find target color: non-bg, not forming complete row/col
    def is_complete_row(c):
        return all(grid[r][c] == c for r in range(h))
    def is_complete_col(r):
        return all(grid[r][c] == r for r in range(w))

    candidates = []
    for color in counts:
        if color != bg_color and not is_complete_row(color) and not is_complete_col(color):
            candidates.append(color)

    if not candidates:
        return grid  # fallback

    target_color = candidates[0]  # Take first candidate

    # Get all pixels of target color
    pixels = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == target_color]

    if not pixels:
        return grid

    # Bounding box
    rows = [p[0] for p in pixels]
    cols = [p[1] for p in pixels]
    min_r, max_r = min(rows), max(rows)
    min_c, max_c = min(cols), max(cols)

    # Determine fill orientation and position
    # Check if there's a full row/col of another color to guide direction
    fill_type = 'row'  # default

    # Look for indicator shapes
    for indicator_color in set(grid[row] for row in range(h)):
        if indicator_color == bg_color or indicator_color == target_color:
            continue
        # Check if indicator forms a complete row
        if indicator_color in set(row[0] for row in grid) or \
           any(all(grid[r][c] == indicator_color for r in range(h)) for c in range(w)):
            pass

    # Heuristic: fill type based on bounding box aspect ratio
    if height := (max_r - min_r + 1) > (width := (max_c - min_c + 1)):
        fill_type = 'row'  # Tall shape -> horizontal fill
    else:
        fill_type = 'col'  # Wide shape -> vertical fill

    # Determine position within that axis
    # Default to max for "push" style transformation
    if fill_type == 'row':
        fill_pos = max_r
    else:
        fill_pos = max_c

    result = [row[:] for row in grid]

    if fill_type == 'row':
        for c in range(w):
            result[fill_pos][c] = 8
    else:
        for r in range(h):
            result[r][fill_pos] = 8

    return result

