def solve_v6(grid):
    """Version with correct position logic"""
    h, w = len(grid), len(grid[0])

    counts = {}
    for r in range(h):
        for c in range(w):
            counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1

    bg = max(counts, key=counts.get)

    candidates = []
    for color in counts:
        if color == bg: continue
        is_full_row = any(all(grid[r][c] == color for r in range(h)) for c in range(w))
        is_full_col = any(all(grid[r][c] == color for r in range(h)) for c in range(w))
        if not is_full_row and not is_full_col:
            candidates.append(color)

    if not candidates: return grid
    target = candidates[0]

    pixels = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == target]
    if not pixels: return grid

    min_r, max_r = min(p[0] for p in pixels), max(p[0] for p in pixels)
    min_c, max_c = min(p[1] for p in pixels), max(p[1] for p in pixels)

    # Look for full-row/column indicators
    indicator_rows = []
    indicator_cols = []

    for c in range(w):
        vals = set(grid[r][c] for r in range(h))
        if len(vals) == 1:
            color = list(vals)[0]
            if color != bg:  # Include all non-bg, even if same as target
                indicator_cols.append((color, c))

    for r in range(h):
        vals = set(grid[r][c] for c in range(w))
        if len(vals) == 1:
            color = list(vals)[0]
            if color != bg:
                indicator_rows.append((color, r))

    # Determine fill type
    if len(indicator_rows) >= len(indicator_cols):
        fill_type = 'row'
    else:
        fill_type = 'col'

    # Position based on relative position to indicators
    if fill_type == 'row':
        if not indicator_rows:
            fill_pos = min_r
        else:
            ind_r = next(r for _, r in indicator_rows)
            # If target starts above indicator, fill at MIN (top)
            # If target starts below indicator, fill at MAX+1 (after bottom)
            if min_r < ind_r:
                fill_pos = min_r  # Above
            else:
                fill_pos = max_r + 1  # Below - but cap at last row
    else:  # col
        if not indicator_cols:
            fill_pos = min_c
        else:
            ind_c = next(c for _, c in indicator_cols)
            # If target left of indicator, fill at min_c (left)
            # If target right of indicator, fill at max_c (right)
            if min_c < ind_c:
                fill_pos = min_c
            else:
                fill_pos = max_c

    result = [row[:] for row in grid]
    if fill_type == 'row':
        for c in range(w): result[fill_pos][c] = 8
    else:
        for r in range(h): result[r][fill_pos] = 8
    return result

